const { Given, When, Then, After } = require('@cucumber/cucumber');
const { expect } = require('chai');

// ===========================
// Background
// ===========================

Given('the app is loaded', function () {
  this.reset();
});

When('the app loads', function () {
  this.reset();
});

// ===========================
// Given steps - todo list setup
// ===========================

Given('the todo list is empty', function () {
  // Already empty after reset
});

Given('the todo list contains {int} item', function (count) {
  // Used as both Given (setup) and Then (assertion)
  const currentCount = this.getTodoCount();
  if (currentCount < count) {
    for (let i = currentCount + 1; i <= count; i++) {
      this.addTodo(`Task ${i}`);
    }
  }
  expect(this.getTodoCount()).to.equal(count);
});

Given('the todo list contains {int} active item', function (count) {
  for (let i = 0; i < count; i++) {
    this.addTodo(`Active task ${i + 1}`);
  }
});

Given('the todo list contains {int} active items', function (count) {
  for (let i = 0; i < count; i++) {
    this.addTodo(`Active task ${i + 1}`);
  }
});

Given('the todo list contains {int} completed items', function (count) {
  for (let i = 0; i < count; i++) {
    this.addTodo(`Completed task ${i + 1}`, true);
  }
});

Given('the todo list contains {int} items', function (count) {
  for (let i = 0; i < count; i++) {
    this.addTodo(`Task ${i + 1}`);
  }
});

Given('the todo list contains {int} active and {int} completed item', function (activeCount, completedCount) {
  for (let i = 0; i < activeCount; i++) {
    this.addTodo(`Active task ${i + 1}`, false);
  }
  for (let i = 0; i < completedCount; i++) {
    this.addTodo(`Completed task ${i + 1}`, true);
  }
});

Given('the todo list contains {int} active and {int} completed items', function (activeCount, completedCount) {
  for (let i = 0; i < activeCount; i++) {
    this.addTodo(`Active task ${i + 1}`, false);
  }
  for (let i = 0; i < completedCount; i++) {
    this.addTodo(`Completed task ${i + 1}`, true);
  }
});

Given('the todo list contains a completed item', function () {
  this.addTodo('Completed task', true);
});

Given('the todo list contains 1 item titled {string}', function (title) {
  this.addTodo(title);
});

Given('the todo list contains 1 completed item titled {string}', function (title) {
  this.addTodo(title, true);
});

Given('the todo list contains 1 active and 1 completed item', function () {
  this.addTodo('Active task', false);
  this.addTodo('Completed task', true);
});

// ===========================
// Given steps - new todo input
// ===========================

Given('the new todo input contains {string}', function (value) {
  const input = this.document.querySelector('.new-todo');
  input.value = value;
});

Given('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  input.value = '';
});

// ===========================
// Given steps - editing mode
// ===========================

Given('the item is in editing mode', function () {
  // Ensure there is exactly one item and put it in editing mode
  let items = this.document.querySelectorAll('.todo-list > li');
  if (items.length === 0) {
    this.addTodo('Buy milk');
    items = this.document.querySelectorAll('.todo-list > li');
  }
  items[0].classList.add('editing');
  // Focus the edit input
  const editInput = items[0].querySelector('.edit');
  if (editInput) {
    // Simulate focus
    this._focusedElement = editInput;
  }
});

Given('the item is in editing mode and the title is {string}', function (title) {
  this.reset();
  this.addTodo(title);
  const items = this.document.querySelectorAll('.todo-list > li');
  items[0].classList.add('editing');
  const editInput = items[0].querySelector('.edit');
  editInput.value = title;
  this._focusedElement = editInput;
});

// ===========================
// Given steps - filter state
// ===========================

Given('the filter {string} is selected', function (filter) {
  if (filter === '#/') {
    this.setFilter('all');
  } else if (filter === '#/active') {
    this.setFilter('active');
  } else if (filter === '#/completed') {
    this.setFilter('completed');
  }
});

Given('the {string} filter is selected', function (filter) {
  this.setFilter(filter.toLowerCase());
});

// ===========================
// When steps - keyboard actions
// ===========================

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(event);
  // Also dispatch keypress and keyup for completeness
  const pressEvent = new this.window.KeyboardEvent('keypress', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(pressEvent);
  const upEvent = new this.window.KeyboardEvent('keyup', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(upEvent);
});

When('I press Enter in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list > li.editing .edit');
  if (!editInput) return;
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  editInput.dispatchEvent(event);
});

When('I press Escape in the edit input', function () {
  const editInput = this.document.querySelector('.todo-list > li.editing .edit');
  if (!editInput) return;
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    which: 27,
    bubbles: true
  });
  editInput.dispatchEvent(event);
});

// ===========================
// When steps - click actions
// ===========================

When('I click the checkbox on the item', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  if (items.length > 0) {
    const toggle = items[0].querySelector('.toggle');
    if (toggle) {
      toggle.click();
    }
  }
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (toggleAll) {
    toggleAll.click();
  }
});

When('I click the destroy button on the item', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  if (items.length > 0) {
    const destroy = items[0].querySelector('.destroy');
    if (destroy) {
      destroy.click();
    }
  }
});

When('I double-click the item label', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  if (items.length > 0) {
    const label = items[0].querySelector('label');
    if (label) {
      const event = new this.window.MouseEvent('dblclick', {
        bubbles: true,
        cancelable: true
      });
      label.dispatchEvent(event);
    }
  }
});

When('I click {string}', function (text) {
  if (text === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    if (btn) {
      btn.click();
    }
  }
});

When('I click the {string} filter link', function (filter) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === filter) {
      a.click();
      return;
    }
  }
});

// ===========================
// When steps - typing in edit input
// ===========================

When('I type {string} in the edit input', function (text) {
  const editInput = this.document.querySelector('.todo-list > li.editing .edit');
  if (!editInput) return;
  editInput.value = text;
  // Dispatch an input event
  const event = new this.window.InputEvent('input', {
    bubbles: true,
    cancelable: true
  });
  editInput.dispatchEvent(event);
});

When('I clear the edit input', function () {
  const editInput = this.document.querySelector('.todo-list > li.editing .edit');
  if (!editInput) return;
  editInput.value = '';
  const event = new this.window.InputEvent('input', {
    bubbles: true,
    cancelable: true
  });
  editInput.dispatchEvent(event);
});

// ===========================
// When steps - mark items
// ===========================

When('I mark all items as complete individually', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  items.forEach(li => {
    const toggle = li.querySelector('.toggle');
    if (toggle && !toggle.checked) {
      toggle.click();
    }
  });
});

When('I mark the item as complete', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  if (items.length > 0) {
    const toggle = items[0].querySelector('.toggle');
    if (toggle && !toggle.checked) {
      toggle.click();
    }
  }
});

When('I mark the item as active', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  if (items.length > 0) {
    const toggle = items[0].querySelector('.toggle');
    if (toggle && toggle.checked) {
      toggle.click();
    }
  }
});

// ===========================
// When steps - page reload
// ===========================

When('the page is reloaded', function () {
  // Simulate reload by creating a fresh window and re-applying state.
  // For now, we just reset. The persistence scenarios will be handled
  // by the production code.
  this.reset();
});

// ===========================
// When steps - focus
// ===========================

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.todo-list > li.editing .edit');
  if (!editInput) return;
  const event = new this.window.FocusEvent('blur', {
    bubbles: true,
    cancelable: true
  });
  editInput.dispatchEvent(event);
});

// ===========================
// Then steps - visibility
// ===========================

Then('main section is not visible', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.equal('none');
});

Then('main section is visible', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.not.equal('none');
});

Then('footer section is not visible', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.equal('none');
});

Then('footer section is visible', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.not.equal('none');
});

Then('the clear-completed button is not visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  expect(btn.style.display).to.equal('none');
});

// ===========================
// Then steps - todo list items
// ===========================



Then('the todo list has {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.equal(count);
});

Then('the todo list has {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.equal(count);
});

Then('the new item reads {string}', function (text) {
  const items = this.document.querySelectorAll('.todo-list > li');
  // The new item is the last one added
  const lastItem = items[items.length - 1];
  const label = lastItem ? lastItem.querySelector('label') : null;
  expect(label).to.not.be.null;
  expect(label.textContent).to.equal(text);
});

Then('the new todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  expect(input.value).to.equal('');
});

Then('the item reads {string}', function (text) {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.be.at.least(1);
  const label = items[0].querySelector('label');
  expect(label).to.not.be.null;
  expect(label.textContent).to.equal(text);
});

// ===========================
// Then steps - item classes
// ===========================

Then('the item has class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.be.at.least(1);
  expect(items[0].classList.contains(className)).to.be.true;
});

Then('the item does not have class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.be.at.least(1);
  expect(items[0].classList.contains(className)).to.be.false;
});

Then('all items have class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.be.at.least(1);
  items.forEach(li => {
    expect(li.classList.contains(className)).to.be.true;
  });
});

Then('no items have class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list > li');
  items.forEach(li => {
    expect(li.classList.contains(className)).to.be.false;
  });
});

// ===========================
// Then steps - toggle-all checkbox
// ===========================

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  expect(toggleAll).to.not.be.null;
  expect(toggleAll.checked).to.be.true;
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  expect(toggleAll).to.not.be.null;
  expect(toggleAll.checked).to.be.false;
});

// ===========================
// Then steps - editing state
// ===========================

Then('the edit input contains the item title', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.be.at.least(1);
  const editInput = items[0].querySelector('.edit');
  expect(editInput).to.not.be.null;
  const label = items[0].querySelector('label');
  expect(label).to.not.be.null;
  expect(editInput.value).to.equal(label.textContent);
});

Then('the edit input is focused', function () {
  // In happy-dom, we can't truly test focus, but we can check
  // that the editing item has its edit input active
  const items = this.document.querySelectorAll('.todo-list > li.editing');
  expect(items.length).to.be.at.least(1);
  const editInput = items[0].querySelector('.edit');
  expect(editInput).to.not.be.null;
  // Verify the edit input exists and the item is in editing mode
  expect(items[0].classList.contains('editing')).to.be.true;
});

// ===========================
// Then steps - todo count
// ===========================

Then('the todo-count shows {string}', function (text) {
  const todoCount = this.document.querySelector('.todo-count');
  expect(todoCount).to.not.be.null;
  expect(todoCount.textContent.replace(/\s+/g, ' ').trim()).to.equal(text);
});

// ===========================
// Then steps - filter state
// ===========================

Then('the {string} filter has class {string}', function (filter, className) {
  const links = this.document.querySelectorAll('.filters a');
  let found = false;
  for (const a of links) {
    // Match by text content (e.g., "Active", "Completed") or by href (e.g., "#/active")
    if (a.textContent.trim() === filter || a.getAttribute('href') === filter) {
      expect(a.classList.contains(className)).to.be.true;
      found = true;
      break;
    }
  }
  expect(found).to.be.true;
});

Then('the item is not visible in the list', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  // The item should be hidden; check that it's not in the visible set
  // This is a filter-aware check: the first item should be display:none or similar
  const visibleItems = this.getVisibleItems();
  const allItems = Array.from(items);
  // If there's an item that's not in the visible set, it's hidden
  const hidden = allItems.some(li => !visibleItems.includes(li));
  expect(hidden).to.be.true;
});

Then('the todo list shows {int} items', function (count) {
  const visible = this.getVisibleItems();
  expect(visible.length).to.equal(count);
});

Then('the todo list shows {int} active item', function (count) {
  const visible = this.getVisibleItems();
  expect(visible.length).to.equal(count);
});

Then('the todo list shows {int} completed item', function (count) {
  const visible = this.getVisibleItems();
  expect(visible.length).to.equal(count);
});

Then('that item is active', function () {
  const items = this.document.querySelectorAll('.todo-list > li');
  expect(items.length).to.be.at.least(1);
  expect(items[0].classList.contains('completed')).to.be.false;
});

